(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  let wy = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.015+t*0.32)*12;
