  wy = Math.cos(s1y*0.022+t*0.38)*8 + Math.sin(s1x*0.02-t*0.42)*6;
  const sx = s1x+wx, sy = s1y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.95],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.05],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*55, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*65, 0.085, 1.8, 1.15]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a = Math.sin(d*f - t*sp)*w;
    const b = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w;
    aS += a; iS += b;
    aS2 += Math.sin(d*f*1.6 - t*sp*1.3 + 0.8)*w*0.5;
    iS2 += Math.sin(d*f*1.1 + t*sp*0.9 + 2.7)*w*0.5;
  }
  const n = src.length;
  const act = aS/n + aS2/n*0.4, inh = iS/n + iS2/n*0.4;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*sy*0.0001+t)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
