  const sp3 = (Math.sin(d2*0.06-a2*4+t*1.8)+Math.sin(d2*0.045+a2*3-t*1.4))*0.25;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const vein = Math.abs(Math.sin(Math.atan2(Math.sin(sx*0.08+t*0.3),Math.cos(sy*0.08-t*0.25))*6+t*0.5))*0.15;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + sp1 + sp2 + sp3)*2.0);
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
